BlockingQueue<Integer> kolejka = new ArrayBlockingQueue<>(5);
AtomicLong suma = new AtomicLong(0);
final int POISON = -1;
Thread producent = new Thread(() -> { try { for (int i=1;i<=50;i++) kolejka.put(i); kolejka.put(POISON); kolejka.put(POISON); } catch (Exception e) {} });
Runnable konsument = () -> { try { while (true) { int v = kolejka.take(); if (v == POISON) break; suma.addAndGet(v); } } catch (Exception e) {} };
Thread k1 = new Thread(konsument), k2 = new Thread(konsument);
producent.start(); k1.start(); k2.start();
producent.join(5_000); k1.join(5_000); k2.join(5_000);
System.out.println(suma.get() == 50L*51/2);

