class BoundedMetricsBuffer {
    BlockingQueue<Integer> kolejka = new ArrayBlockingQueue<>(10);
    AtomicLong produkcje = new AtomicLong(0), konsumpcje = new AtomicLong(0);
    void put(int v) throws InterruptedException { kolejka.put(v); produkcje.incrementAndGet(); }
    int take() throws InterruptedException { int v = kolejka.take(); konsumpcje.incrementAndGet(); return v; }
}
BoundedMetricsBuffer bufor = new BoundedMetricsBuffer();
final int POISON = -1;
CountDownLatch producenciDone = new CountDownLatch(2);
for (int p=0;p<2;p++) new Thread(() -> { try { for (int i=0;i<15;i++) bufor.put(i); } catch (Exception e) {} finally { producenciDone.countDown(); } }).start();
Thread[] konsumenci = new Thread[2];
for (int k=0;k<2;k++) konsumenci[k] = new Thread(() -> { try { while (true) { int v = bufor.take(); if (v == POISON) break; } } catch (Exception e) {} });
for (Thread kn : konsumenci) kn.start();
producenciDone.await(5, TimeUnit.SECONDS);
for (int k=0;k<2;k++) bufor.put(POISON);
for (Thread kn : konsumenci) kn.join(5_000);
System.out.println(bufor.produkcje.get()+" "+bufor.konsumpcje.get());

BlockingQueue<String> zadania = new LinkedBlockingQueue<>();
