record DelayedTask(String nazwa, long readyAtMillis) implements Delayed {
    public long getDelay(TimeUnit unit) { return unit.convert(readyAtMillis - System.currentTimeMillis(), TimeUnit.MILLISECONDS); }
    public int compareTo(Delayed o) { return Long.compare(getDelay(TimeUnit.MILLISECONDS), o.getDelay(TimeUnit.MILLISECONDS)); }
}
DelayQueue<DelayedTask> kolejka = new DelayQueue<>();
long now = System.currentTimeMillis();
int[] opoznienia = {300,100,500,200,400};
for (int d : opoznienia) kolejka.put(new DelayedTask("zadanie-"+d, now+d));
for (int i=0;i<5;i++) { DelayedTask t = kolejka.take(); System.out.println(t.nazwa()); }

