record Order(int id, boolean bledne) {}
BlockingQueue<Order> kolejka = new LinkedBlockingQueue<>();
ConcurrentHashMap<String, AtomicInteger> statystyki = new ConcurrentHashMap<>();
CountDownLatch wszystkieDone = new CountDownLatch(30);
for (int i=1;i<=30;i++) kolejka.put(new Order(i, i%5==0));
ExecutorService pool = Executors.newFixedThreadPool(3);
for (int k=0;k<3;k++) pool.submit(() -> { try { while (wszystkieDone.getCount() > 0) { Order o = kolejka.poll(1, TimeUnit.SECONDS); if (o == null) break; statystyki.computeIfAbsent("PRZYJETE", key -> new AtomicInteger(0)).incrementAndGet(); if (o.bledne()) statystyki.computeIfAbsent("BLAD", key -> new AtomicInteger(0)).incrementAndGet(); else statystyki.computeIfAbsent("PRZETWORZONE", key -> new AtomicInteger(0)).incrementAndGet(); wszystkieDone.countDown(); } } catch (Exception e) {} });
wszystkieDone.await(10, TimeUnit.SECONDS);
System.out.println(statystyki);
pool.shutdown(); pool.awaitTermination(5, TimeUnit.SECONDS);
